export const isPro=s=>['pro','independent','mlb'].includes(s.stage);
export function createPlayer(name='',role='batter',seed=Date.now()>>>0){const s={version:CONFIG.version,careerId:newCareerId(),seed:seed>>>0,player:{name:name.trim().slice(0,24)||randomPlayerName(),role:role==='pitcher'?'pitcher':'batter',abilities:{},talent:1,peakAge:30},year:CONFIG.startYear,age:CONFIG.startAge,stage:'elementary',grade:1,period:0,team:'青葉ジュニア',environmentId:null,training:'balanced',scout:0,salary:0,totalSalary:0,proYears:0,retired:false,pending:null,records:[],tournaments:[],drafts:[],nationalHistory:[],awards:[],contracts:[],teams:[{year:CONFIG.startYear,stage:'elementary',team:'青葉ジュニア'}],timeline:[{year:CONFIG.startYear,text:'小学校入学・青葉ジュニアで野球を始める'}],news:['はじめてのユニフォーム。ここから、あなたの野球人生が始まる。'],current:emptyStats(),periodResults:[],lastSummary:null};s.player.talent=between(s,.86,1.18);s.player.peakAge=integer(s,29,34);for(const k of Object.keys(ABILITIES))if(k!=='throwing')s.player.abilities[k]=between(s,11,24);initializeTraits(s);migrateTraits(s);if(s.player.genius)s.news.push('同年代とは違う打球と身のこなし。周囲が「天才かもしれない」とささやき始めた。');migrateCareer(s);migrateProfile(s);initializeDevelopment(s);return s;}
export function environment(s){if(s.stage==='middle')return MIDDLE.find(e=>e.id===s.environmentId);if(s.stage==='high'){const school=SCHOOLS.find(e=>e.id===s.environmentId);return {...school,opportunity:school.opportunity+(s.schoolOffers?.some(o=>o.id===school.id)?.1:0)};}if(s.stage==='elementary')return {growth:1,opportunity:1,competition:10,games:9,scout:.4,national:.1};if(s.stage==='mlb')return {growth:1.08,opportunity:1,competition:78,games:162,scout:1,national:0};if(s.stage==='pro')return {growth:1,opportunity:1,competition:64,games:143,scout:1,national:0};return {...ROUTES.find(e=>e.id===s.stage),opportunity:1,national:.2};}
const log=(s,text)=>s.timeline.push({year:s.year,text});
function tournament(s,env,absence=0){const season=CONFIG.seasons[s.period];let name,threshold,regional;
 if(s.stage==='high'){regional=season==='夏'?'夏季地方大会':season==='春'?'春季県大会':'秋季地区大会';name=season==='夏'?'夏の甲子園':season==='春'?'春の甲子園':'秋季全国大会';threshold=env.national*(season==='春'?.68:1);}
 else if(s.stage==='middle'){regional=`${season}季地区大会`;name=env.tournament;threshold=env.national;}
 else if(s.stage==='elementary'){regional=`${season}季少年野球大会`;name='全国少年野球大会';threshold=.09;}
 else {regional=s.stage==='corporate'?'都市対抗予選':`${season}季リーグ戦`;name=s.stage==='corporate'?'都市対抗野球':s.stage==='overseas'?'全米大学選手権':'全国大学選手権';threshold=.2;}
 threshold=clamp(threshold+(overall(s)-env.competition)*.003,.015,.85);const qualified=random(s)<threshold;const regionalResult=qualified?'優勝':pick(s,['準優勝','ベスト4','ベスト8','初戦敗退']);const regionalGames=qualified?5:regionalResult==='準優勝'?4:regionalResult==='ベスト4'?3:regionalResult==='ベスト8'?2:1;
 const make=(title,result,games,national=false)=>{const n=s.player.role==='pitcher'?Math.max(1,Math.round(games*.6)):games;const stats=simulateStats(s,Math.round(n*(1-absence)),env.competition+(national?10:0));s.tournaments.push({year:s.year,stage:s.stage,season,name:title,result,national,koshien:title.includes('甲子園'),team:s.team,stats});s.current=sumStats([s.current,stats]);return stats;};
 const parts=[make(regional,regionalResult,regionalGames)];s.news.push(`${regional}：${regionalResult}`);
 if(qualified){const result=random(s)<clamp(.13+(overall(s)-env.competition)*.004,.03,.4)?'優勝':pick(s,['準優勝','ベスト4','ベスト8','初戦敗退']);const games=result==='優勝'?5:result==='準優勝'?5:result==='ベスト4'?4:result==='ベスト8'?3:1;parts.push(make(name,result,games,true));s.scout=clamp(s.scout+(result==='優勝'?9:4)*env.scout,0,99);log(s,`${name} ${result}`);s.news.push(`${name}に出場！ ${result}`);}return sumStats(parts);}
export function advance(s){if(s.retired||s.injuryAdvice||s.pending||s.employment||s.contractOffers.length)return false;if(s.retirementAdvice&&!s.retirementAdvice.answered)return false;if(prepareNational(s)||prepareRosterDecision(s))return false;beginDevelopmentSeason(s);s.market=null;s.news=[];if(s.period===0){assignPitchRole(s);assignBatterPosition(s);}const env=environment(s);const professional=isPro(s);const changes=grow(s,env,professional);const issue=injury(s);applyNewInjuryGrowth(s,changes,issue);assignBatterRole(s,env.competition);const ov=overall(s);const firstThreshold=s.stage==='mlb'?80:65,fringeThreshold=s.stage==='mlb'?67:48;let roster=professional?(s.stage==='independent'?'主力':ov>=firstThreshold?'一軍':ov>=fringeThreshold?'一軍 / 二軍':'二軍'):(ov>=env.competition?'レギュラー':'控え / 途中出場');let opportunity=professional?(s.stage==='independent'?1:ov>=firstThreshold?between(s,.8,1):ov>=fringeThreshold?between(s,.25,.6):between(s,.03,.15)):clamp(env.opportunity+(ov-env.competition)*.012,.25,1.1);if(s.activeContract?.endYear>=s.year&&s.activeContract.guarantees?.regular)opportunity=Math.max(opportunity,.85);if(s.stage==='pro'&&s.contractStatus==='development'){opportunity=0;roster='育成・二軍';}if(s.player.role==='batter'&&['defense','runner','pinch','pinchAce'].includes(s.player.batterRole)&&s.contractStatus!=='development')opportunity=Math.max(opportunity,.7);if(issue){opportunity*=1-issue.lost;s.news.push(`${issue.name}で出場機会が${Math.round(issue.lost*100)}%減少。${issue.daysLeft?'復帰まで残り約'+issue.daysLeft+'日。':'復帰。'}`);}if(s.seasonImpact?.year===s.year){opportunity*=1-s.seasonImpact.loss;if(s.seasonImpact.loss)s.news.push('代表戦での故障により出場機会が減少。');if(s.seasonImpact.difficulty)s.news.push('代表戦後の調整不足が今季の成績に影響。');}let games=env.games*opportunity;if(s.player.role==='pitcher')games*=professional?pitchGameFactor(s):(!['elementary','middle','high'].includes(s.stage)&&reliefRole(s)?.8:.4);const loss=1-(1-(issue?.lost||0))*(1-(s.seasonImpact?.year===s.year?s.seasonImpact.loss:0));const majorSelection=s.stage!=='mlb'||s.activeContract?.guarantees?.regular||majorReady(s);if(!majorSelection)opportunity=0;const daily=['pro','mlb'].includes(s.stage)?simulateDailyRoster(s,!majorSelection?0:loss<1?Math.min(1,opportunity/(1-loss)):ov>=(s.stage==='mlb'?80:65)?.9:.35,issue):null;s.currentRoster=daily;if(daily)observeDevelopmentRoster(s,daily);const levels=daily?simulateRegisteredLevels(s,daily):null;const stats=levels?levels.first:simulateStats(s,games,env.competition+(s.seasonImpact?.year===s.year?s.seasonImpact.difficulty||0:0));if(levels)roster=s.stage==='mlb'?(levels.first.games>=levels.second.games?'メジャー中心':'マイナー中心'):rosterFromGames(levels,s.contractStatus);s.currentLevels=levels;s.current=sumStats([s.current,stats]);let tournamentStats=emptyStats();if(!professional&&(!issue||issue.lost<1))tournamentStats=tournament(s,env,issue?.lost||0);for(const fn of hooks.afterPeriod)fn(s);s.scout=clamp(s.scout+Math.max(0,ov-35)*.055*env.scout+between(s,-1,2),0,99);const result={year:s.year,season:professional?'シーズン':CONFIG.seasons[s.period],stage:s.stage,team:s.team,stats:sumStats([stats,tournamentStats]),levels,roster,injury:issue,overall:overall(s),changes};s.periodResults.push(result);s.lastSummary=result;
 if(professional||s.period===2)finishYear(s,roster);else s.period++;return true;}
function finishYear(s,roster){
 const record={year:s.year,age:s.age,stage:s.stage,grade:s.grade,team:s.team,stats:{...s.current},levels:['pro','mlb'].includes(s.stage)?s.currentLevels:null,dailyRoster:s.currentRoster||null,mlbServiceDays:s.stage==='mlb'?s.currentRoster?.service||0:0,salary:isPro(s)?s.salary:0,roster,overall:overall(s),rank:integer(s,1,['pro','mlb'].includes(s.stage)?leagueTeamCount(s.team,s.stage):6),pitchRole:s.player.pitchRole,position:s.player.position,batterRole:s.player.batterRole,contractStatus:s.contractStatus||'registered',number:s.player.number,awards:[]};
 if(isPro(s)){
  settleSalary(s,record);s.proYears++;const st=s.current;
  teamSeasonResult(s,record);seasonAwards(s,record);settleIncome(s,record);
 }
 recordFAService(s,record,s.lastSummary?.injury);youthSelection(s,record);schoolScouting(s);s.records.push(record);checkSeasonRecords(s,record);reviewPostingChallenge(s,record);s.news.unshift(`${s.year}年の成績を記録しました。`);for(const fn of hooks.afterYear)fn(s,record);
 if(s.injuryRetirement){s.injuryRetirement=false;s.injuryAdvice={year:s.year,name:s.health?.name||'大けが'};log(s,'大けがにより今後の現役生活について相談。療養して続行するか、引退するかを選択');}
 if(s.stage==='pro'&&s.contractStatus==='development'&&record.levels?.second.games&&overall(s)>=60&&random(s)<.65){s.contractStatus='registered';s.salary=Math.max(SALARY_MODEL.npbFloor,s.salary);s.activeContract=null;s.news.push('獲得：支配下登録。来季から一軍出場が可能に。');log(s,'育成から支配下選手へ昇格');}
 if(s.age>=SALARY_MODEL.maxAge){if(isPro(s))s.contracts.push({year:s.year,team:s.team,salary:record.salary,nextSalary:0,roster,yearsLeft:0});retire(s);log(s,'50歳のシーズンを終え、年齢上限により現役引退');return;}
 if(isPro(s)){prepareRenewal(s,record);reviewEmployment(s,record);if(!s.employment&&!s.contractOffers.length)retirementReview(s,record);}
 if(s.employment){s.pending=null;nextYear(s);return;}
 if(s.stage==='elementary'&&s.grade===6)s.pending={type:'middle'};
 else if(s.stage==='middle'&&s.grade===3)s.pending={type:'high'};
 else if(s.stage==='high'&&s.grade===3||['university','overseas'].includes(s.stage)&&s.grade===4||s.stage==='corporate'||s.stage==='independent')s.pending={type:'career',draft:draft(s)};
 else{nextYear(s);queueMarketNotices(s);}
}
function nextYear(s){s.year++;s.age++;s.grade++;s.period=0;s.current=emptyStats();s.currentLevels=null;s.currentRoster=null;}
export function advanceYear(s){if(s.retired||s.injuryAdvice||s.pending||s.employment||s.contractOffers.length||s.rosterDecision||s.retirementAdvice&&!s.retirementAdvice.answered)return;const year=s.year;do{if(!advance(s))break;}while(s.year===year&&!s.pending&&!s.retired);}
export function choose(s,id){if(!s.pending)throw new Error('進路を選ぶ時期ではありません');const type=s.pending.type;if(['university','overseas'].includes(id)&&!mayEnterUniversity(s))throw Error('大学進学は高校卒業時のみ選択できます。卒業後の再入学はできません。');let target;if(type==='middle')target=MIDDLE.find(x=>x.id===id);else if(type==='high')target=SCHOOLS.find(x=>x.id===id);else if(type==='career'&&id==='mlb'&&s.pending.draft.overseasOffer)target={name:s.pending.draft.overseasOffer.team};else if(type==='career'&&id==='pro'&&s.pending.draft.type!=='指名なし')target={name:s.pending.draft.team};else if(id==='stay'&&['corporate','independent'].includes(s.stage)){s.pending=null;nextYear(s);return;}else if(type==='career'){if(id==='independent'&&!s.pending.draft.independentOffer)throw Error('独立リーグの入団テストに合格していません。');target=ROUTES.find(x=>x.id===id);}if(!target)throw new Error('選択できない進路です');const prev=s.stage;const offered=s.pending.draft;nextYear(s);s.stage=type==='middle'?'middle':type==='high'?'high':id;s.environmentId=target.id||null;s.grade=1;s.team=target.name;s.pending=null;s.contractStatus='registered';if(s.stage==='mlb'){s.proEntry??={route:prev==='overseas'?'overseasDirect':'other',year:s.year,team:s.team};s.salary=offered.overseasOffer.salary;s.news=['海外ドラフトから'+s.team+'へ入団。'];}else if(s.stage==='pro'){s.domesticEntry??={route:prev,draftYear:offered.year};s.contractStatus=offered.type==='育成'?'development':'registered';s.salary=offered.salary;s.news=[`${s.team}と契約。契約金${offered.bonus.toLocaleString()}万円、年俸${offered.salary.toLocaleString()}万円。`];}else if(s.stage==='independent'){s.salary=240;s.news=['独立リーグでプロ生活をスタート。'];}else{s.salary=0;s.news=[`${target.name}で、新しい一歩を踏み出す。`];}s.contractOffers=[];s.employment=null;if(isPro(s))setContract(s,s.salary);else s.activeContract=null;assignNumber(s);s.teams.push({year:s.year,stage:s.stage,team:s.team,from:prev});log(s,`${target.name} ${['middle','high','university','overseas'].includes(s.stage)?'入学・入部':'入団'}`);}
export function retire(s,route='auto'){if(s.retired)return false;if(s.current.games&&!s.records.some(r=>r.year===s.year)){s.records.push({year:s.year,age:s.age,stage:s.stage,grade:s.grade,team:s.team,stats:{...s.current},salary:0,roster:'引退時点',overall:overall(s),rank:0,awards:[],partial:true});}legacyHonors(s);s.careerTypes=classifyCareer(s);s.retired=true;s.rosterDecision=null;s.injuryAdvice=null;s.postingReport=null;s.pending=null;s.nationalOffers=[];s.employment=null;s.contractOffers=[];s.market=null;log(s,`${s.age}歳で現役引退。${s.proYears}年間のプロ生活に幕。`);s.news.push('おつかれさまでした。選手としての人生を終え、新しい道へ。');startAfterlife(s,route);return true;}
export const stageLabel=s=>`${STAGES[s.stage]}${isPro(s)?`・${s.proYears+1}年目`:['corporate'].includes(s.stage)?`・${s.grade}年目`:`・${s.grade}年`}`;

export function chooseEmployment(s,id){const e=s.employment;if(!e||s.retired)throw Error('現在、進路の提示はありません。');const o=e.options.find(x=>x.id===id);if(!o)throw Error('選択できない進路です。');if(STAFF_ROLES[o.role]){s.postCareer={year:s.year,team:o.team,role:STAFF_ROLES[o.role].label,salary:o.salary,guaranteed:!!o.guaranteed};retire(s);log(s,`${o.team}の${s.postCareer.role}に就任。年俸${money(o.salary)}（選手の生涯年俸には含めません）`);return;}const from=e.from;s.team=o.team;s.stage=o.stage;s.contractStatus=o.development?'development':'registered';s.grade=1;s.environmentId=o.stage==='corporate'?'corporate':null;s.employment=null;s.pending=null;s.retirementAdvice=null;s.contractOffers=[];if(isPro(s))setContract(s,o.salary,o.years||1);else{s.salary=0;s.activeContract=null;}assignNumber(s);s.teams.push({year:s.year,stage:s.stage,team:s.team,from});log(s,`${s.team}で現役続行を選択`);s.news=[`${s.team}で現役を続けます。`];}

export function continueAfterInjury(s){if(!s.injuryAdvice||s.retired)throw Error('療養の相談は届いていません。');s.injuryAdvice=null;s.timeline.push({year:s.year,text:'大けがの説明を受け、療養しながら現役続行を選択'});}
